-- ============================================================
--  Proposal Maker — DEMO DATA (optional)
--  11 sample proposals for different clients, services, templates
--  and statuses, with views, activity, client answers and a
--  typed e-signature. Also a demo company profile (Webanza Tech)
--  and two demo users:
--      admin@demo.com  / admin123   (admin)
--      editor@demo.com / editor123  (editor)
--  Change these passwords after logging in!
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET FOREIGN_KEY_CHECKS = 1;

-- Move all demo dates forward so they are relative to TODAY
-- (the demo was created on 2026-10-17). Without this, the demo
-- proposals would look old or be marked "Expired" straight away.
SET @shift = DATEDIFF(CURDATE(), '2026-10-17');
UPDATE proposals SET
    proposal_date   = DATE_ADD(proposal_date,   INTERVAL @shift DAY),
    expiry_date     = DATE_ADD(expiry_date,     INTERVAL @shift DAY),
    first_viewed_at = DATE_ADD(first_viewed_at, INTERVAL @shift DAY),
    last_viewed_at  = DATE_ADD(last_viewed_at,  INTERVAL @shift DAY),
    sent_at         = DATE_ADD(sent_at,         INTERVAL @shift DAY),
    responded_at    = DATE_ADD(responded_at,    INTERVAL @shift DAY),
    created_at      = DATE_ADD(created_at,      INTERVAL @shift DAY),
    updated_at      = DATE_ADD(updated_at,      INTERVAL @shift DAY);
UPDATE proposal_activity  SET created_at = DATE_ADD(created_at, INTERVAL @shift DAY);
UPDATE proposal_responses SET created_at = DATE_ADD(created_at, INTERVAL @shift DAY);
UPDATE users SET created_at = DATE_ADD(created_at, INTERVAL @shift DAY);
