INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (411,1,99,'b3e61305a73','cover','{\"eyebrow\":\"Website Development Proposal\",\"title\":\"{{proposal_title}}\",\"subtitle\":\"A modern, fast and conversion-focused website built to grow your business.\",\"title_size\":46,\"for_label\":\"Prepared for\",\"by_label\":\"Prepared by\",\"show_client\":true,\"show_by\":true,\"show_date\":true,\"show_number\":true,\"show_expiry\":false,\"image\":\"uploads/demo/hero-web.jpg\",\"logo_size\":46,\"shapes\":true,\"layout\":\"template\",\"show_toc\":true}',0,0);
INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (412,1,100,'b6a27ebd0e6','heading','{\"eyebrow\":\"Introduction\",\"text\":\"Dear {{client_name}},\",\"subtitle\":\"\",\"level\":\"h2\",\"style\":\"template\",\"number\":\"\"}',0,0);
INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (413,1,100,'bc9bfaca570','text','{\"html\":\"<p>Thank you for considering <b>{{company_name}}</b> for your new website. We have reviewed your requirements and prepared this proposal outlining our recommended approach, deliverables, timeline and investment.</p><p>Our goal is simple: to build a website for <b>{{client_company}}</b> that looks exceptional, loads instantly, ranks well on search engines and turns visitors into customers.</p>\",\"size\":0,\"line_height\":0,\"columns\":\"1\"}',1,0);
INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (414,1,100,'b84baaa3aba','quote','{\"text\":\"Your website is your best salesperson — it works 24 hours a day, 7 days a week.\",\"author\":\"{{company_name}}\",\"role\":\"\",\"style\":\"card\"}',2,0);
INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (415,1,101,'b1389b0cc8b','heading','{\"eyebrow\":\"About Us\",\"text\":\"Who We Are\",\"subtitle\":\"\",\"level\":\"h2\",\"style\":\"template\",\"number\":\"\"}',0,0);
