INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (453,1,107,'b8c0c56f01a','pricing_table','{\"title\":\"Project Investment\",\"show_description\":true,\"show_qty\":true,\"discount_type\":\"percent\",\"discount\":10,\"tax_rate\":0,\"tax_label\":\"Tax\",\"note\":\"All prices are in {{currency}}. This quotation is valid until {{expiry_date}}.\",\"rows\":[{\"service\":\"UI/UX Design\",\"description\":\"Custom design for up to 8 pages\",\"qty\":1,\"price\":900},{\"service\":\"Website Development\",\"description\":\"Responsive build + CMS\",\"qty\":1,\"price\":1600},{\"service\":\"SEO Setup\",\"description\":\"On-page SEO, sitemap, analytics\",\"qty\":1,\"price\":300},{\"service\":\"Speed & Security\",\"description\":\"Optimisation, SSL, backups\",\"qty\":1,\"price\":200}]}',1,0);
