INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (837,8,206,'b4ef41b8361','text','{\"html\":\"<p>Thank you for considering <b>{{company_name}}</b> for your new website. We have reviewed your requirements and prepared this proposal outlining our recommended approach, deliverables, timeline and investment.</p><p>Our goal is simple: to build a website for <b>{{client_company}}</b> that looks exceptional, loads instantly, ranks well on search engines and turns visitors into customers.</p>\",\"size\":0,\"line_height\":0,\"columns\":\"1\"}',1,0);
