INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (875,8,212,'baff08f3004','timeline','{\"items\":[{\"date\":\"Week 1\",\"title\":\"Discovery & Planning\",\"text\":\"Kick-off meeting, requirements and sitemap.\"},{\"date\":\"Week 2-3\",\"title\":\"UI/UX Design\",\"text\":\"Homepage and inner page designs with two revision rounds.\"},{\"date\":\"Week 4-6\",\"title\":\"Development\",\"text\":\"Responsive build, CMS setup and integrations.\"},{\"date\":\"Week 7\",\"title\":\"Testing & QA\",\"text\":\"Cross-browser testing, speed and SEO checks.\"},{\"date\":\"Week 8\",\"title\":\"Launch & Training\",\"text\":\"Deployment, handover and team training.\"}]}',4,0);
