INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (877,8,213,'b2fa46f2b45','pricing_table','{\"title\":\"Project Investment\",\"show_description\":true,\"show_qty\":true,\"discount_type\":\"percent\",\"discount\":0,\"tax_rate\":5,\"tax_label\":\"VAT\",\"note\":\"All prices are in {{currency}}. This quotation is valid until {{expiry_date}}.\",\"rows\":[{\"service\":\"UI/UX Design\",\"description\":\"Custom design for up to 8 pages\",\"qty\":1,\"price\":3240},{\"service\":\"Website Development\",\"description\":\"Responsive build + CMS\",\"qty\":1,\"price\":5760},{\"service\":\"SEO Setup\",\"description\":\"On-page SEO, sitemap, analytics\",\"qty\":1,\"price\":1080},{\"service\":\"Speed & Security\",\"description\":\"Optimisation, SSL, backups\",\"qty\":1,\"price\":720}]}',1,0);
