INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (953,9,230,'b0209b46bcc','terms','{\"title\":\"\",\"html\":\"<ol><li><b>Acceptance.</b> This proposal becomes a binding agreement once accepted in writing or electronically by {{client_company}}.</li><li><b>Payment.</b> Invoices are payable within 7 days. Work begins once the initial deposit has been received.</li><li><b>Revisions.</b> The number of revision rounds is limited to what is specified in this proposal. Additional changes are billed at our standard hourly rate.</li><li><b>Client responsibilities.</b> The client agrees to provide content, feedback and approvals in a timely manner. Delays may affect the timeline.</li><li><b>Intellectual property.</b> Upon full payment, ownership of the final deliverables transfers to the client. {{company_name}} may showcase the work in its portfolio.</li><li><b>Third-party costs.</b> Domains, hosting, premium plugins, stock assets and advertising spend are not included unless stated.</li><li><b>Confidentiality.</b> Both parties agree to keep confidential information private.</li><li><b>Cancellation.</b> Either party may terminate with 14 days written notice. Work completed up to that date is payable.</li><li><b>Results.</b> SEO results depend on many external factors; no specific ranking can be guaranteed.</li><li><b>Minimum term.</b> SEO services require a minimum 6-month commitment.</li><li><b>Validity.</b> This proposal is valid until {{expiry_date}}.</li></ol>\",\"size\":12}',1,0);
INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (954,9,231,'b0a633af9fc','heading','{\"eyebrow\":\"Next Steps\",\"text\":\"Let\'s Get Started\",\"subtitle\":\"Accepting this proposal is simple — review the details, click \\\"Accept Proposal\\\" and we will schedule your kick-off call within 48 hours.\",\"level\":\"h2\",\"style\":\"template\",\"number\":\"\"}',0,0);
INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (955,9,231,'b1425262cd3','numbered_list','{\"title\":\"\",\"style\":\"circle\",\"items\":[{\"text\":\"Accept this proposal online or sign below.\"},{\"text\":\"Receive your deposit invoice and project onboarding pack.\"},{\"text\":\"Kick-off meeting to align on goals, content and timeline.\"}]}',1,0);
