INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (1047,11,255,'bf2f86f603e','cover','{\"eyebrow\":\"Mobile App Development Proposal\",\"title\":\"{{proposal_title}}\",\"subtitle\":\"A powerful, scalable mobile app for Android and iOS.\",\"title_size\":46,\"for_label\":\"Prepared for\",\"by_label\":\"Prepared by\",\"show_client\":true,\"show_by\":true,\"show_date\":true,\"show_number\":true,\"show_expiry\":false,\"image\":\"uploads/demo/hero-app.jpg\",\"logo_size\":46,\"shapes\":true,\"layout\":\"template\",\"show_toc\":true}',0,0);
