INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (1049,11,256,'b23f86f6b9d','text','{\"html\":\"<p>Dear {{client_name}},</p><p>{{company_name}} is pleased to propose the design and development of a cross-platform mobile application for <b>{{client_company}}</b>. The app will deliver a fast, intuitive experience on both Android and iOS, backed by a secure cloud backend and an admin panel.</p>\",\"size\":0,\"line_height\":0,\"columns\":\"1\"}',1,0);
INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (1050,11,256,'bb1e8ed8895','heading','{\"eyebrow\":\"Goals\",\"text\":\"App Objectives\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"template\",\"number\":\"\"}',2,0);
INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (1051,11,256,'b9ed093ff4d','list','{\"title\":\"\",\"marker\":\"circle-check\",\"columns\":\"1\",\"items\":[{\"text\":\"Deliver a seamless experience on Android and iOS\"},{\"text\":\"Increase customer engagement and retention\"},{\"text\":\"Enable secure user accounts and data\"},{\"text\":\"Provide real-time notifications\"},{\"text\":\"Give your team full control via an admin panel\"}]}',3,0);
INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (1052,11,256,'b1ce9b2cb80','heading','{\"eyebrow\":\"Audience\",\"text\":\"Target Audience\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"template\",\"number\":\"\"}',4,0);
INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (1053,11,256,'b6eafc15a66','text','{\"html\":\"<p>The primary audience is smartphone users aged 18–45 who value speed, simplicity and convenience. The design will prioritise one-handed use and accessibility.</p>\",\"size\":0,\"line_height\":0,\"columns\":\"1\"}',5,0);
