INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (1055,11,257,'bc179e10a63','service_cards','{\"columns\":\"2\",\"show_price\":true,\"items\":[{\"icon\":\"palette\",\"title\":\"UI/UX Design\",\"description\":\"Modern, intuitive app screens.\",\"features\":\"User flows\\nWireframes\\nHigh-fidelity UI\\nClickable prototype\",\"price\":\"\",\"bg\":\"\",\"color\":\"\"},{\"icon\":\"android2\",\"title\":\"Android Development\",\"description\":\"Native-quality Android app.\",\"features\":\"Flutter / React Native\\nMaterial design\\nOffline support\\nPlay Store ready\",\"price\":\"\",\"bg\":\"\",\"color\":\"\"},{\"icon\":\"apple\",\"title\":\"iOS Development\",\"description\":\"Polished iPhone experience.\",\"features\":\"Human Interface guidelines\\nFace ID support\\nApp Store ready\\niPad compatible\",\"price\":\"\",\"bg\":\"\",\"color\":\"\"},{\"icon\":\"server\",\"title\":\"Backend / API\",\"description\":\"Secure, scalable cloud backend.\",\"features\":\"REST API\\nDatabase design\\nCloud hosting\\nPayment gateway\",\"price\":\"\",\"bg\":\"\",\"color\":\"\"}]}',1,0);
