INSERT INTO `proposal_blocks` (`id`, `proposal_id`, `page_id`, `uid`, `type`, `data`, `sort_order`, `is_hidden`) VALUES (1057,11,258,'bb281843ec0','feature_cards','{\"columns\":\"3\",\"style\":\"card\",\"align\":\"left\",\"items\":[{\"icon\":\"key\",\"title\":\"Authentication\",\"text\":\"Email, phone OTP and social login with secure tokens.\"},{\"icon\":\"bell\",\"title\":\"Notifications\",\"text\":\"Push notifications with segmentation and scheduling.\"},{\"icon\":\"kanban\",\"title\":\"Admin Panel\",\"text\":\"Web dashboard to manage users, content and analytics.\"}]}',1,0);
